import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

/** Reads apps/web/.env.local, then .env.development.local (generated by pnpm local:init); later wins. */
export function webEnv(): Record<string, string> {
  const entries = ['.env.local', '.env.development.local'].flatMap((name) => {
    const path = fileURLToPath(new URL(`../../apps/web/${name}`, import.meta.url));
    if (!existsSync(path)) return [];
    return readFileSync(path, 'utf8')
      .split('\n')
      .filter((line) => /^[A-Z_]+=/.test(line))
      .map((line) => {
        const i = line.indexOf('=');
        return [line.slice(0, i), line.slice(i + 1).trim()] as const;
      });
  });
  return Object.fromEntries(entries);
}

export function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`Set ${name} (see e2e/README.md)`);
  return value;
}
